import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Entry is a single ledger entry. Change is expressed in cents.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// FormatLedger renders the entries as a formatted ledger for the given
// currency (USD or EUR) and locale (en-US or nl-NL). Entries are sorted
// by date, then description, then change. The input slice is not
// modified.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	if currency != "USD" && currency != "EUR" {
		return "", errors.New("invalid currency")
	}
	if locale != "en-US" && locale != "nl-NL" {
		return "", errors.New("invalid locale")
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.SliceStable(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	if locale == "nl-NL" {
		b.WriteString("Datum      | Omschrijving              | Verandering\n")
	} else {
		b.WriteString("Date       | Description               | Change\n")
	}
	for _, entry := range sorted {
		line, err := formatEntry(locale, currency, entry)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}

// formatEntry renders a single ledger line.
func formatEntry(locale, currency string, entry Entry) (string, error) {
	date, err := formatDate(locale, entry.Date)
	if err != nil {
		return "", err
	}
	amount := formatAmount(locale, currency, entry.Change)
	return fmt.Sprintf("%s | %s | %13s\n", date, formatDescription(entry.Description), amount), nil
}

// formatDate validates a "Y-m-d" date and renders it in the locale's
// conventional order: MM/DD/YYYY for en-US, DD-MM-YYYY for nl-NL.
func formatDate(locale, date string) (string, error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", errors.New("invalid date")
	}
	year, month, day := date[0:4], date[5:7], date[8:10]
	if locale == "nl-NL" {
		return day + "-" + month + "-" + year, nil
	}
	return month + "/" + day + "/" + year, nil
}

// formatDescription pads the description to 25 characters, or truncates
// overlong ones with an ellipsis.
func formatDescription(desc string) string {
	if len(desc) > 25 {
		return desc[:22] + "..."
	}
	return desc + strings.Repeat(" ", 25-len(desc))
}

// formatAmount renders an amount in cents in the locale's convention:
// en-US uses "$1,234.56" with parentheses around negatives, nl-NL uses
// "$ 1.234,56" with a trailing "-" for negatives.
func formatAmount(locale, currency string, cents int) string {
	symbol := "$"
	if currency == "EUR" {
		symbol = "€"
	}
	negative := cents < 0
	if negative {
		cents = -cents
	}
	whole, frac := cents/100, cents%100
